// #4805fb רכיב אזהרת העלאה ידנית — экран «הוספת מכרז» (/tenders/new), роль ADMIN.
// Тендер не создаётся (кнопка «הוספת מכרז» не нажимается) — данных не остаётся.
import { test, expect, Page } from '@playwright/test';
import { authState, qaFile, qaName, uploadItem } from '../helpers/tenderflow';

test.use({ storageState: authState('admin') });

const WARNING =
  'שים לב: בהעלאה ידנית של קובץ ייתכן שיוחסרו מסמכים או נספחים רלוונטיים של המכרז. מומלץ להזין את הקישור הישיר לעמוד המכרז כדי לאפשר קליטה וניטור של כלל המסמכים והעדכונים.';
const FILES_LABEL = 'קבצי המכרז (אפשר לבחור כמה קבצים)';

async function openAddTender(page: Page) {
  await page.goto('/tenders/new');
  await expect(page.getByRole('heading', { name: 'הוספת מכרז' })).toBeVisible();
}

test.describe('רכיב אזהרת העלאה ידנית', () => {
  test('בחירה בהעלאת קבצים מציגה את האזהרה בנוסח המדויק #4805fb @desktop @prod-safe', async ({ page }) => {
    await openAddTender(page);
    // До выбора ручной загрузки предупреждения нет
    await expect(page.getByText(WARNING, { exact: true })).toHaveCount(0);

    await page.getByLabel('העלאת קבצים').check();

    // AC1: текст посимвольно; AC2: появляется при выборе ручной загрузки вместо ссылки
    await expect(page.getByText(WARNING, { exact: true })).toBeVisible();
    await expect(page.getByRole('button', { name: 'המשך בהעלאה ידנית' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'הזנת קישור במקום' })).toBeVisible();
  });

  test('אפשר להמשיך בהעלאה ידנית למרות האזהרה #4805fb @desktop @prod-safe', async ({ page }) => {
    await openAddTender(page);
    await page.getByLabel('העלאת קבצים').check();
    await page.getByRole('button', { name: 'המשך בהעלאה ידנית' }).click();

    // AC3: предупреждение закрыто, доступна загрузка файлов
    await expect(page.getByText(WARNING, { exact: true })).toHaveCount(0);
    const input = page.getByLabel(FILES_LABEL, { exact: true });
    await expect(input).toBeAttached();

    const file = qaFile(qaName('mtu'), 'pdf');
    await input.setInputFiles(file);
    await expect(uploadItem(page, file.name).getByRole('status')).toHaveText('מוכן להעלאה');
    await expect(page.getByRole('button', { name: 'הוספת מכרז', exact: true })).toBeEnabled();
  });

  test('אפשר לחזור ולבחור הזנת קישור במקום העלאה #4805fb @desktop @prod-safe', async ({ page }) => {
    await openAddTender(page);
    await page.getByLabel('העלאת קבצים').check();
    await expect(page.getByText(WARNING, { exact: true })).toBeVisible();

    await page.getByRole('button', { name: 'הזנת קישור במקום' }).click();

    // AC4: выбран ввод ссылки, предупреждение не висит, поле ссылки на месте
    await expect(page.getByLabel('הזנת קישור')).toBeChecked();
    await expect(page.getByText(WARNING, { exact: true })).toHaveCount(0);
    await expect(page.getByLabel('קישור לעמוד המכרז')).toBeVisible();

    // Повторный выбор файлов снова показывает предупреждение
    await page.getByLabel('העלאת קבצים').check();
    await expect(page.getByText(WARNING, { exact: true })).toBeVisible();
  });
});
